local _, ns = ...
local Translate = ns.Lore.Translate

Translate("frFR", "wetlands", {
	title = "Les Paluns",
	aliases = { "Paluns" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Paluns sont un vaste pays de marécages, de roseaux et d'eaux noires et lentes qui s'étend au nord des montagnes de Khaz Modan. La brume y flotte une bonne partie de l'année. Une seule grande route les traverse : elle sort de {link:dun-algaz}Dun Algaz{/link} au sud, file vers le nord en longeant les ruines d'anciennes forteresses naines et s'achève au viaduc de Thandol, le pont qui relie les terres naines aux royaumes humains du nord. Une seconde route tourne vers l'ouest et la mer, où le {link:menethil-harbor}Port de Menethil{/link} assure la veille de l'{link:alliance}Alliance{/link} sur la côte. Ce fut toujours une terre rude, riche en crocilisques et en raptors, pauvre en confort. C'est aujourd'hui aussi une terre en guerre.]=],
		},
		{
			title = "Origines",
			text = [=[Aucune chronique ne dit qui éleva le premier la pierre dans ces marais. Les nains les revendiquent depuis bien des siècles. À l'est se dresse la forteresse montagnarde de {link:grim-batol}Grim Batol{/link}, jadis siège du clan Wildhammer. Pendant la guerre des Trois Marteaux, les {link:dark-iron-dwarves}Sombrefer{/link} frappèrent Grim Batol, et la sombre sorcellerie qui y fut déchaînée laissa la forteresse souillée. Les Wildhammer l'abandonnèrent et partirent au nord, vers les cimes des {link:the-hinterlands}Hinterlands{/link}. La {link:explorers-league}Ligue des explorateurs{/link} trouve encore des choses plus anciennes sous la boue : des os de grandes bêtes, et des pierres gravées d'une écriture qu'aucun {link:dwarves}nain{/link} n'écrivit.]=],
		},
		{
			title = "Le temps présent",
			text = [=[Le {link:menethil-harbor}Port de Menethil{/link} tient la côte ouest pour l'{link:alliance}Alliance{/link}, sous l'autorité des nains du {link:kingdom-of-ironforge}royaume d'Ironforge{/link}. Au-delà de ses murs, les Paluns se défont. Des saboteurs {link:dark-iron-dwarves}Sombrefer{/link} ont brisé le viaduc de Thandol et pris {link:dun-modr}Dun Modr{/link}, et les survivants du régiment qui les tenait attendent dans les ruines une réserve qui n'arrive jamais. Les {link:dragonmaw-clan}orcs Dragonmaw{/link}, battus et dispersés après la {link:second-war}Deuxième Guerre{/link}, ont trouvé un nouveau chef et un nouveau camp. Ils ont poussé jusque dans {link:dun-algaz}Dun Algaz{/link} et menacent de couper Menethil du {link:loch-modan}Loch Modan{/link}. Aux {link:whelgar-s-excavation-site}Excavations de Whelgar{/link}, des raptors ont tué la plupart des fouilleurs de la {link:explorers-league}Ligue des explorateurs{/link}. Au-dessus de ces fouilles, une brume a commencé à descendre des montagnes, des lumières vacillent sur les hauteurs, et des créations de pierre marchent là où personne n'a marché depuis des âges. La seule nouvelle porteuse d'espoir vient de la mer : de nouveaux navires partent désormais de Menethil pour {link:southshore}Southshore{/link} et, au-delà, pour {link:auberdine}Auberdine{/link}.]=],
		},
		{
			title = "Habitants",
			text = [=[• {b}Les nains d'{link:ironforge}Ironforge{/link}.{/b} Soldats, mineurs, prêtres et érudits tiennent le {link:menethil-harbor}Port de Menethil{/link}, le camp devant {link:dun-modr}Dun Modr{/link} et les fouilles de la {link:explorers-league}Ligue des explorateurs{/link}.
• {b}Les gens de Menethil.{/b} Des humains des anciens royaumes travaillent sur ses quais, dans ses tavernes et ses tanneries aux côtés des nains.
• {b}Le {link:dragonmaw-clan}clan Dragonmaw{/link}.{/b} Des {link:orcs}orcs{/link} qui chevauchaient jadis des dragons rouges à la guerre, aujourd'hui campés dans les collines à l'est de la route.
• {b}Les {link:dark-iron-dwarves}Sombrefer{/link}.{/b} Leurs saboteurs, leurs sapeurs et leurs démonistes tiennent Dun Modr et la colline de Morneforge.
• {b}Les gnolls Poil-moussu.{/b} Un clan de {link:gnolls}gnolls{/link} des marais, devenu trop nombreux pour la terre qui le nourrit.
• {b}Les murlocs Branchies-bleues.{/b} Des {link:murlocs}murlocs{/link} qui razzient la côte et les navires marchands qui la longent.
• {b}Les morts noyés.{/b} Des marins maudits hantent encore les épaves de la flotte perdue, sur le rivage nord-ouest.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}Les Trois Marteaux.{/b} {link:grim-batol}Grim Batol{/link} se tut après la guerre des trois clans, et les Wildhammer laissèrent les Paluns derrière eux.
• {b}La {link:second-war}Deuxième Guerre{/link}.{/b} La {link:horde}Horde{/link} envahit Khaz Modan. Le {link:dragonmaw-clan}clan Dragonmaw{/link} fit de Grim Batol sa place forte, et les orcs bâtirent un port sur la côte ouest pour frapper {link:hillsbrad-foothills}Hillsbrad{/link} par la mer. Des dragons rouges sous commandement {link:orcs}orc{/link} incendièrent la {link:third-fleet}Troisième flotte{/link} de {link:kul-tiras}Kul Tiras{/link} au large de ces côtes.
• {b}Menethil.{/b} L'amiral {link:daelin-proudmoore}Daelin Proudmoore{/link} chassa les orcs de leur port, et l'{link:alliance}Alliance{/link} éleva son propre port sur le même terrain, nommé d'après le roi {link:terenas-menethil}Terenas Menethil{/link}.
• {b}Le temps présent.{/b} Les {link:dark-iron-dwarves}Sombrefer{/link} se soulevèrent au nord, les Dragonmaw revinrent à l'est, et les réserves d'{link:ironforge}Ironforge{/link} furent envoyées combattre sur d'autres fronts.]=],
		},
		{
			title = "Traditions des Paluns",
			text = [=[• Les peaux de crocilisque de la tannerie de Menethil se vendent dans les ports du monde entier.
• Un esprit du marais, appelé le Gardien vert, marche parmi les crocilisques à l'est de l'embranchement vers {link:dun-modr}Dun Modr{/link}. On dit à ceux qui le cherchent qu'ils ne reviendront pas.
• Les gnolls Poil-moussu brûlent des arbres vivants pour se chauffer, et le Gardien vert ne le leur a pas pardonné.
• Le dernier survivant de la {link:third-fleet}Troisième flotte{/link} dit qu'en rêve il entend encore les gémissements de ses frères noyés.]=],
		},
	},
})

Translate("frFR", "menethil-harbor", {
	title = "Port de Menethil",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Port de Menethil est le port de l'{link:alliance}Alliance{/link} sur la côte ouest des {link:wetlands}Paluns{/link}. Il se dresse sur le terrain où la {link:horde}Horde{/link} construisit jadis des navires pour la {link:second-war}Deuxième Guerre{/link}, et une grande part du bois et du fer qu'elle vola à Khaz Modan traîne encore sur ses quais. Son donjon porte le nom du roi {link:terenas-menethil}Terenas Menethil{/link}. Les nains d'{link:ironforge}Ironforge{/link} le commandent, et le capitaine {link:captain-stoutfist}Stoutfist{/link} prépare sa défense depuis la salle de guerre du donjon de Menethil. Des navires partent de ses jetées pour {link:auberdine}Auberdine{/link}, pour {link:theramore-isle}Theramore{/link} de l'autre côté de la mer, et désormais aussi pour {link:southshore}Southshore{/link}. À la taverne de l'Eau-profonde, marins, érudits, espions et un survivant ivre de la {link:third-fleet}Troisième flotte{/link} partagent les mêmes tables.]=],
		},
	},
})

Translate("frFR", "dun-modr", {
	title = "Dun Modr",
	sections = {
		{
			title = "Résumé",
			text = [=[Dun Modr est une ville naine du nord des {link:wetlands}Paluns{/link}, sur la route du viaduc de Thandol. Un régiment d'{link:ironforge}Ironforge{/link} la tenait, ainsi que le pont au-delà. Les {link:dark-iron-dwarves}Sombrefer{/link} frappèrent d'abord le pont, puis tombèrent sur la ville avant que le régiment ne pût se ressaisir, et la plupart des nains furent tués. {link:longbraid-the-grim}Longbraid le Sinistre{/link} sonna la retraite. Ce qui reste de son régiment campe désormais juste devant les murs, tandis que soldats, sapeurs et démolisseurs Sombrefer tiennent les rues. On a vu une créature de feu enchaînée parmi eux, et un élémentaire appelé Modr arpente les ruines.]=],
		},
	},
})

Translate("frFR", "thandol-span", {
	title = "Viaduc de Thandol",
	aliases = { "Le viaduc de Thandol" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le viaduc de Thandol est le grand pont à la lisière nord des {link:wetlands}Paluns{/link}. Il franchit une gorge profonde vers les {link:arathi-highlands}Hautes-terres d'Arathi{/link} et porte la route principale entre Khaz Modan et les terres du nord. Les {link:dark-iron-dwarves}Sombrefer{/link} firent sauter son pont ouest lors d'une embuscade, et beaucoup de nains périrent avec lui, parmi lesquels le frère de {link:longbraid-the-grim}Longbraid le Sinistre{/link}. Le plan fut ourdi par un Sombrefer appelé {link:kam-deepfury}Kam Deepfury{/link}. Ses agents cachèrent d'autres explosifs de l'autre côté de la gorge pour abattre ce qui restait. Si le viaduc tombe, les nains perdent leur principale voie de ravitaillement vers le nord.]=],
		},
	},
})

Translate("frFR", "whelgar-s-excavation-site", {
	title = "Excavations de Whelgar",
	aliases = { "Fouilles de Whelgar" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Excavations de Whelgar sont des fouilles de la {link:explorers-league}Ligue des explorateurs{/link} au milieu des {link:wetlands}Paluns{/link}. L'équipe du prospecteur {link:prospector-whelgar}Whelgar{/link} mettait au jour d'anciennes reliques quand elle commença à trouver des os énormes. Peu après, les raptors tachetés du marais déferlèrent sur le site. Beaucoup de fouilleurs moururent. Trois survivants tiennent bon sur un promontoire au-dessus des ruines de leur camp. Parmi les découvertes se trouve une tablette brisée gravée dans l'écriture des titans, la {link:goaz-stone}pierre de Goaz{/link}. Plus haut dans les collines au sud-est, au-delà des anciennes fouilles, se trouve un second camp ouvert par la Ligue, et de là un chemin mène au {link:excavation-site}Site d'excavation{/link}.]=],
		},
	},
})

Translate("frFR", "dun-algaz", {
	title = "Dun Algaz",
	sections = {
		{
			title = "Résumé",
			text = [=[Dun Algaz est le col de montagne entre le {link:loch-modan}Loch Modan{/link} et les {link:wetlands}Paluns{/link}, gardé à son débouché sud par les nains du poste d'Algaz. C'est la seule route par laquelle les soldats d'{link:ironforge}Ironforge{/link} peuvent atteindre le {link:menethil-harbor}Port de Menethil{/link} par voie de terre. Les {link:dragonmaw-clan}orcs Dragonmaw{/link} s'en sont toujours tenus aux collines, mais ils sont désormais descendus en force dans le col, menés par un seigneur de guerre appelé {link:ma-ruk-wyrmscale}Ma'ruk Wyrmscale{/link}. Personne à Menethil ne sait ce qui les y a poussés. S'ils tiennent Dun Algaz, le port sera seul.]=],
		},
	},
})

Translate("frFR", "grim-batol", {
	title = "Grim Batol",
	sections = {
		{
			title = "Résumé",
			text = [=[Grim Batol est une forteresse montagnarde à l'extrême est des {link:wetlands}Paluns{/link}, derrière les portes des Dragonmaw. Elle fut bâtie par les nains Wildhammer, qui la quittèrent après la guerre des Trois Marteaux, quand une sombre sorcellerie souilla ses salles. Pendant la {link:second-war}Deuxième Guerre{/link}, le {link:dragonmaw-clan}clan Dragonmaw{/link} en fit sa place forte. Là, ils retinrent enchaînée {link:alexstrasza}Alexstrasza{/link}, reine des dragons rouges, par le pouvoir d'un artefact créé par {link:deathwing}Aile-de-mort{/link}, et élevèrent ses petits comme montures de guerre. La reine a depuis été libérée. Des dragons rouges se rassemblent aujourd'hui devant les portes de Grim Batol, et ils ne tolèrent pas les étrangers.]=],
		},
	},
})

Translate("frFR", "angerfang-encampment", {
	title = "Campement de Hargnecroc",
	sections = {
		{
			title = "Résumé",
			text = [=[Le campement de Hargnecroc est le camp de guerre des {link:dragonmaw-clan}orcs Dragonmaw{/link}, dans les collines à l'est de la route des {link:wetlands}Paluns{/link}. Après la {link:second-war}Deuxième Guerre{/link}, les rares Dragonmaw qui survécurent à la vengeance des dragons rouges fuirent {link:grim-batol}Grim Batol{/link} et se cachèrent dans ces montagnes. Ici, sous les ordres du chef {link:chieftain-nek-rosh}Nek'rosh{/link}, ils ont repris des forces. Leurs bannières de guerre flottent au-dessus du camp, leurs centurions et leurs gardiens des ombres s'y entraînent, et leurs catapultes de siège sont prêtes pour la marche sur le {link:menethil-harbor}Port de Menethil{/link}.]=],
		},
	},
})

Translate("frFR", "dragonmaw-retreat", {
	title = "Dragonmaw Retreat",
	sections = {
		{
			title = "Résumé",
			text = [=[Dragonmaw Retreat est un repaire caché des {link:dragonmaw-clan}orcs Dragonmaw{/link} dans les collines de l'est des {link:wetlands}Paluns{/link}. Le clan y entrepose des armes pour des soldats qu'il n'a pas encore armés. Ses guerriers ne sont pas seulement des combattants : des lieurs d'âmes et des récupérateurs marchent parmi eux, et l'on y a vu un draconien, courbé et soumis. Le capitaine {link:captain-stoutfist}Stoutfist{/link} verrait volontiers la réserve emportée avant qu'elle ne puisse servir. Ce que les orcs entendent récupérer, les nains ne peuvent que le deviner.]=],
		},
	},
})

Translate("frFR", "mosshide-fen", {
	title = "Marais des Poils-moussus",
	sections = {
		{
			title = "Résumé",
			text = [=[Le marais des Poils-moussus est une étendue marécageuse au sud des {link:wetlands}Paluns{/link}, près de la porte naine d'Algaz. Il tire son nom des gnolls Poil-moussu. Les gnolls vivent paisiblement dans les marais depuis de nombreuses années, mais leur nombre a grandi. Ils piétinent les buissons et les fleurs du marais et coupent ses arbres pour leurs feux, et ils portent de grossiers silex pour les allumer. L'esprit appelé le Gardien vert les a désignés comme une plaie sur la terre.]=],
		},
	},
})

Translate("frFR", "sundown-marsh", {
	title = "Marais du couchant",
	sections = {
		{
			title = "Résumé",
			text = [=[Le marais du couchant s'étend au nord des {link:wetlands}Paluns{/link}, un bas pays humide de mares et de roseaux. Les gnolls Poil-moussu y chassent aussi, avec leurs mystiques et leurs dominants. Des choses plus étranges sortent de l'eau. Des rampants des marais se traînent dans les chenaux, et de plus grands seigneurs des marais se dressent parmi eux. {link:rethiel-the-greenwarden}Le Gardien vert{/link} les appelle des cloques fiévreuses sur la terre, nées d'une infection que personne ne sait expliquer, et voudrait les voir rendus au marais.]=],
		},
	},
})

Translate("frFR", "saltspray-glen", {
	title = "Vallon des embruns",
	sections = {
		{
			title = "Résumé",
			text = [=[Le vallon des embruns est un creux du nord-ouest des {link:wetlands}Paluns{/link}, ouvert au vent venu de la mer. C'est un pays de raptors. Les raptors tranchegueules qui y chassent doivent leur nom à leurs dents, assez longues et acérées pour percer les écailles d'un dragonnet, et l'on dit que leurs œufs renferment des jaunes aussi gros qu'une tête de {link:gnomes}gnome{/link}. Le {link:dwarves}nain{/link} {link:howin-kindfeather}Howin Kindfeather{/link} envoie des chasseurs ici pour les uns comme pour les autres.]=],
		},
	},
})

Translate("frFR", "ironbeard-s-tomb", {
	title = "Tombe d'Ironbeard",
	sections = {
		{
			title = "Résumé",
			text = [=[La tombe d'Ironbeard est un ancien lieu de sépulture {link:dwarves}nain{/link} au nord des {link:wetlands}Paluns{/link}, non loin de {link:dun-modr}Dun Modr{/link}. Quel que fût Ironbeard, la tombe a survécu à son nom. Des limons cramoisis dégoulinants y rampent désormais et engloutissent ce qu'ils touchent. Une femme de Menethil appelée {link:sida}Sida{/link} s'y rend encore une fois par semaine, limons ou pas, et dut un jour les fuir en y laissant son sac.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique ne dit qui était Ironbeard, quand il fut mis au repos ici, ni pourquoi {link:sida}Sida{/link} visite sa tombe.]=],
		},
	},
})

Translate("frFR", "direforge-hill", {
	title = "Colline de Morneforge",
	sections = {
		{
			title = "Résumé",
			text = [=[La colline de Morneforge s'élève à l'est de {link:dun-modr}Dun Modr{/link}. C'est le principal camp des {link:dark-iron-dwarves}Sombrefer{/link} dans les {link:wetlands}Paluns{/link}. D'ici, leurs sapeurs creusent, leurs saboteurs partent et leurs démolisseurs transportent la poudre qui brisa le viaduc de Thandol. Leur maître en ces terres est le démoniste {link:balgaras-the-foul}Balgaras le Répugnant{/link}, que l'on voit rarement dans les combats. Les nains du camp de {link:longbraid-the-grim}Longbraid{/link} savent que la guerre pour le nord se décidera sur cette colline.]=],
		},
	},
})

Translate("frFR", "raptor-ridge", {
	title = "Crête des raptors",
	sections = {
		{
			title = "Résumé",
			text = [=[La crête des raptors est une haute corniche rocheuse au nord-est des {link:wetlands}Paluns{/link}. C'est le domaine des raptors tranchegueules, et une grande matriarche de leur espèce règne sur la crête. Peu de chasseurs y montent de bon gré. Ceux qui le font viennent pour les dents et les œufs des tranchegueules, et ils en reviennent couverts de cicatrices.]=],
		},
	},
})

Translate("frFR", "bluegill-marsh", {
	title = "Marais des Branchies-bleues",
	sections = {
		{
			title = "Résumé",
			text = [=[Le marais des Branchies-bleues se trouve sur la côte au nord du {link:menethil-harbor}Port de Menethil{/link}. Les murlocs Branchies-bleues sont remontés des eaux profondes et ont bâti leurs huttes le long de son rivage. Ils s'en prennent aux pêcheurs et aux marchands sur la route, et quand le navire marchand {i}Blind Princess{/i} passa, ils jetèrent par-dessus bord une grande partie de sa cargaison. Un {link:murlocs}murloc{/link} appelé Gobbler mène des raids depuis l'embouchure de la rivière et se replie toujours à l'abri des huttes.]=],
		},
	},
})

Translate("frFR", "black-channel-marsh", {
	title = "Marais des eaux-noires",
	sections = {
		{
			title = "Résumé",
			text = [=[Le marais des eaux-noires est un dédale d'eau sombre et de roseaux à l'ouest des {link:wetlands}Paluns{/link}, entre le {link:menethil-harbor}Port de Menethil{/link} et les fouilles de la {link:explorers-league}Ligue des explorateurs{/link}. Ses chenaux sont le repaire des crocilisques géants que prisent les tanneurs de Menethil, et les raptors tachetés des collines descendent jusqu'à ses bords pour chasser. L'apprenti du tanneur vint ici écorcher des crocilisques, et les crocilisques lui prirent une jambe.]=],
		},
	},
})

Translate("frFR", "the-green-belt", {
	title = "La Ceinture verte",
	aliases = { "Ceinture verte" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Ceinture verte est une longue vallée d'herbe et d'eau à l'est des {link:wetlands}Paluns{/link}, à l'est de la route là où elle bifurque vers {link:dun-modr}Dun Modr{/link}. Des dragonnets cramoisis y nichent. Des ours rendus fous par quelque maladie errent sur ses pentes. {link:rethiel-the-greenwarden}Le Gardien vert{/link}, esprit du marais, marche ici parmi les crocilisques, et les orcs des collines ne sont jamais loin.]=],
		},
	},
})

Translate("frFR", "the-lost-fleet", {
	title = "La flotte perdue",
	sections = {
		{
			title = "Résumé",
			text = [=[La flotte perdue est le cimetière de navires de la côte nord-ouest des {link:wetlands}Paluns{/link}. C'est ici que la {link:third-fleet}Troisième flotte{/link} de {link:kul-tiras}Kul Tiras{/link} brûla et sombra sous le feu des dragons rouges pendant la {link:second-war}Deuxième Guerre{/link}. Ses coques gisent encore dans les hauts-fonds. Les équipages ne trouvèrent pas tous le repos. Quelque chose de maudit fut caché à bord de l'un des navires, et son pouvoir retient les marins et les soldats de marine noyés dans leurs ponts pourrissants, leur capitaine parmi eux.]=],
		},
	},
})

Translate("frFR", "thelgen-rock", {
	title = "Rocher de Thelgen",
	sections = {
		{
			title = "Résumé",
			text = [=[Le rocher de Thelgen est une grotte dans les collines du sud des {link:wetlands}Paluns{/link}, au sud-est des fouilles de {link:prospector-whelgar}Whelgar{/link}. Des araignées l'emplissent, et leur venin est si puissant que les alchimistes de Menethil ont besoin de leurs glandes intactes pour fabriquer de l'antivenin. Une grande araignée appelée la Veuve sangsue chasse près de son entrée. Le chemin qui passe le rocher de Thelgen grimpe dans les hautes terres où se trouve le {link:excavation-site}Site d'excavation{/link}.]=],
		},
	},
})

Translate("frFR", "the-drunken-dwarf", {
	title = "The Drunken Dwarf",
	sections = {
		{
			title = "Résumé",
			text = [=[The Drunken Dwarf est une taverne ouverte depuis peu au sud des {link:wetlands}Paluns{/link}, près de la route qui sort de {link:dun-algaz}Dun Algaz{/link}. C'est une vue bienvenue pour les voyageurs qui ont franchi le col avec des orcs à leurs trousses. Aurian Highgrove tient le comptoir. Les Firebrew, Bhalir et Agriel, tiennent la cuisine. Son nom est une promesse que la plupart de ses clients sont heureux de tenir.]=],
		},
	},
})

Translate("frFR", "captain-stoutfist", {
	title = "Capitaine Stoutfist",
	subtitle = "Commandant du donjon de Menethil",
	found = "La salle de guerre du donjon de Menethil",
	hint = [=[Cherchez le capitaine qui prépare la défense de Menethil dans la salle de guerre de son donjon.]=],
	allegiance = "Royaume d'Ironforge",
	aliases = { "Stoutfist" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le capitaine Stoutfist commande le {link:menethil-harbor}Port de Menethil{/link} pour le royaume d'{link:ironforge}Ironforge{/link}. Depuis la salle de guerre du donjon de Menethil, il surveille trois ennemis à la fois : les {link:dark-iron-dwarves}Sombrefer{/link} au nord, les Dragonmaw dans les collines, et les orcs qui étranglent désormais le col de {link:dun-algaz}Dun Algaz{/link}. Il a peu de soldats et moins encore de renforts. Il fait appel à tout combattant qui arrive par le col.]=],
		},
		{
			title = "Importance",
			text = [=[Stoutfist est l'homme dont dépend toute la côte ouest. Si Menethil tombe, l'{link:alliance}Alliance{/link} perd son port du nord et la route entre {link:ironforge}Ironforge{/link} et la mer.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il reçoit les rapports de {link:valstag-ironjaw}Valstag Ironjaw{/link} sur l'avancée des Dragonmaw dans {link:dun-algaz}Dun Algaz{/link}.
• Il envoie des combattants contre le campement de Hargnecroc pour prendre les bannières de guerre des orcs.
• Il ordonne l'incendie des catapultes Dragonmaw, et la mort de leur chef.
• Il veut que les armes de {link:dragonmaw-retreat}Dragonmaw Retreat{/link} soient prises avant de pouvoir armer de nouveaux soldats.]=],
		},
	},
	chapters = {
		{
			title = "Le coup de Nek'rosh",
			hint = "Découvrez ce que les Dragonmaw ont construit dans leur camp.",
			text = [=[Les combattants qui avaient attaqué Hargnecroc revinrent avec plus que des bannières. Ils avaient vu des catapultes. {link:chieftain-nek-rosh}Nek'rosh{/link} comptait assiéger Menethil, et avec {link:dun-algaz}Dun Algaz{/link} aux mains des orcs, aucun secours ne pourrait atteindre le port à temps. Stoutfist distribua de l'amadou et donna un ordre simple : brûler les engins, puis abattre la bête à la gorge.]=],
		},
		{
			title = "La statuette du roi",
			hint = "Portez la statuette retrouvée au donjon de Menethil.",
			text = [=[La statuette d'argent reprise aux murlocs était destinée à son donjon. Stoutfist était fier de tenir un mémorial du {link:terenas-menethil}roi Terenas{/link}, dont son donjon porte le nom, mais il savait ce qu'était son port : un lieu calme dans une tempête d'ennemis. Il craignait ce que les Dragonmaw feraient d'un tel objet, et il l'envoya à {link:stormwind-city}Stormwind{/link} pour qu'il y soit gardé en sûreté.]=],
		},
	},
	mentions = {
		{ text = "Au rapport auprès du capitaine Stoutfist" },
		{ text = "Bannières de guerre" },
		{ text = "Le coup de {link:chieftain-nek-rosh}Nek'rosh{/link}" },
		{ text = "Vaincre {link:chieftain-nek-rosh}Nek'rosh{/link}" },
		{ text = "Rapporter la statuette" },
		{ text = "Un ami de la famille, pour le généralissime" },
		{ text = "Un ami de la famille, pour la cathédrale" },
		{ text = "Désarmement forcé" },
	},
	bonds = {
		{ id = "valstag-ironjaw", name = "Valstag Ironjaw", note = "lui apporte les rapports de Dun Algaz" },
		{ id = "chieftain-nek-rosh", name = "Chef Nek'rosh", note = "ennemi" },
		{ id = "karl-boran", name = "Karl Boran", note = "lui envoya la statuette" },
		{ id = "bolvar-fordragon", name = "Bolvar Fordragon", note = "le généralissime à qui il la confie" },
	},
})

