	},
})

Translate("frFR", "karl-boran", {
	title = "Karl Boran",
	subtitle = "Agent de la Marine marchande",
	found = "Les quais du Port de Menethil",
	hint = [=[Parlez à l'homme des quais qui paie pour la sécurité des marchands.]=],
	allegiance = "Marine marchande",
	sections = {
		{
			title = "Résumé",
			text = [=[Karl Boran veille sur les marchands qui commercent par le {link:menethil-harbor}Port de Menethil{/link}. Les murlocs Branchies-bleues ont rendu cette tâche difficile. Ils harcèlent la route côtière et attaquent les navires, et quand ils frappèrent le navire marchand {i}Blind Princess{/i}, ils entraînèrent une grande partie de sa cargaison dans la mer. La pièce la plus précieuse était une statuette d'argent, un mémorial du roi {link:terenas-menethil}Terenas Menethil{/link}. Boran paie bien pour la récupérer.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il met à prix la tête du {link:murlocs}murloc{/link} Gobbler et des siens.
• Il envoie des chercheurs fouiller les huttes des murlocs pour retrouver la cargaison perdue du {i}Blind Princess{/i}.]=],
		},
	},
	mentions = {
		{ text = "Des griffes venues des profondeurs" },
		{ text = "Récupérer les marchandises" },
		{ text = "Rapporter la statuette" },
	},
	bonds = {
		{ id = "captain-stoutfist", name = "Capitaine Stoutfist", note = "la statuette était destinée à son donjon" },
	},
})

Translate("frFR", "first-mate-fitzsimmons", {
	title = "Second Fitzsimmons",
	subtitle = "Dernier survivant de la Troisième flotte",
	found = "La taverne de l'Eau-profonde, Port de Menethil",
	hint = [=[Offrez à boire au marin qui noie ses souvenirs à la taverne de l'Eau-profonde.]=],
	allegiance = "Kul Tiras (autrefois)",
	aliases = { "Fitzsimmons" },
	sections = {
		{
			title = "Résumé",
			text = [=[Fitzsimmons était second à bord du {i}Wave Mistress{/i}, un vaisseau de ligne de la {link:third-fleet}Troisième flotte{/link} de {link:kul-tiras}Kul Tiras{/link}. Lors du dernier voyage de la flotte, des dragons rouges montés par des orcs s'abattirent sur elle et l'incendièrent au large de la côte des {link:wetlands}Paluns{/link}. Lui seul survécut. Il passe aujourd'hui ses journées à la taverne de l'Eau-profonde, sentant l'aigre et assoiffé, et ses nuits à rêver de ses frères noyés.]=],
		},
		{
			title = "Importance",
			text = [=[Fitzsimmons est la mémoire vivante de {link:third-fleet}la flotte maudite{/link}. Lui seul sait qu'une chose terrible fut cachée à bord de l'un de ses navires, et que son pouvoir empêche les morts de reposer.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il raconte l'histoire de la {link:third-fleet}Troisième flotte{/link} à quiconque lui offre de l'hydromel.
• Il demande que ses frères maudits soient libérés.
• Il envoie des chercheurs auprès du fantôme du capitaine {link:captain-halyndor}Halyndor{/link} pour la clé du coffre-fort du navire.
• Il indique le chemin du Gardien vert, et avertit celui qui le cherche de ne pas y aller.]=],
		},
	},
	chapters = {
		{
			title = "La flotte maudite",
			hint = "Déliez la langue du vieux marin avec une chope d'hydromel.",
			text = [=[Un verre frais en main, Fitzsimmons raconte les choses sans détour. La flotte leva l'ancre ; les dragons vinrent ; les navires brûlèrent et sombrèrent. Il ne sait pas pourquoi il a survécu. Il maudit son capitaine de les avoir menés à leur perte, et il boit à ses frères dans leurs tombes liquides.]=],
		},
		{
			title = "L'Œil maudit",
			hint = "Ouvrez le coffre-fort de l'Intrepid.",
			text = [=[Le capitaine {link:captain-halyndor}Halyndor{/link} avait gardé la chose enfermée dans son coffre-fort à bord de l'{i}Intrepid{/i}. Quand on ouvrit le coffre, il contenait un orbe noirci qui palpitait d'une lumière maladive : un Œil de Paleth, souillé par le chagrin dont il avait été témoin. Fitzsimmons refusa d'y toucher. Il l'envoya au prêtre {link:glorin-steelbrow}Glorin Steelbrow{/link}.]=],
		},
	},
	mentions = {
		{ text = "{link:third-fleet}La Troisième flotte{/link}" },
		{ text = "L'équipage maudit" },
		{ text = "Lever la malédiction" },
		{ text = "{link:rethiel-the-greenwarden}Le Gardien vert{/link}" },
	},
	bonds = {
		{ id = "captain-halyndor", name = "Capitaine Halyndor", note = "son ancien capitaine, qu'il blâme" },
		{ id = "glorin-steelbrow", name = "Glorin Steelbrow", note = "reçut l'Œil" },
		{ id = "rethiel-the-greenwarden", name = "Rethiel le Gardien vert", note = "l'esprit contre lequel il met en garde" },
	},
})

Translate("frFR", "glorin-steelbrow", {
	title = "Glorin Steelbrow",
	subtitle = "Prêtre de Menethil",
	found = "La taverne de l'Eau-profonde, Port de Menethil",
	hint = [=[Trouvez le prêtre nain qui connaît les secrets de la flotte engloutie.]=],
	allegiance = "Royaume d'Ironforge · Église de la Lumière sacrée",
	aliases = { "Glorin" },
	sections = {
		{
			title = "Résumé",
			text = [=[Glorin Steelbrow est un prêtre {link:dwarves}nain{/link} de la {link:holy-light}Lumière sacrée{/link} qui vit au {link:menethil-harbor}Port de Menethil{/link}. Il connaît mieux que la plupart les épaves de la {link:third-fleet}Troisième flotte{/link}. Un navire qui naviguait avec elle, le {i}Flying Osprey{/i}, transportait une cargaison de fer de forgelumière, un métal qui frappe avec une force sacrée. Glorin sait où il se trouve et qui peut le travailler. Pourtant, quand l'Œil maudit de Paleth tomba entre ses mains, il ne put le purifier. Les Yeux furent faits par des prêtres humains, et seul un maître humain pouvait en guérir un.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il envoie des chercheurs à l'épave du {i}Flying Osprey{/i} pour y trouver le fer de forgelumière.
• Il envoie l'Œil maudit de Paleth à l'{link:archbishop-benedictus}archevêque Benedictus{/link}, à {link:stormwind-city}Stormwind{/link}.]=],
		},
	},
	mentions = {
		{ text = "La flotte maudite" },
		{ text = "Fer de forgelumière" },
		{ text = "Les lingots perdus" },
		{ text = "Bras béni" },
		{ text = "L'Œil de Paleth" },
		{ text = "Purifier l'Œil" },
	},
	bonds = {
		{ id = "first-mate-fitzsimmons", name = "Second Fitzsimmons", note = "un ivrogne à qui il ne paie pas à boire" },
		{ id = "archbishop-benedictus", name = "Archevêque Benedictus", note = "peut purifier l'Œil" },
	},
})

Translate("frFR", "innkeeper-helbrek", {
	title = "Aubergiste Helbrek",
	subtitle = "Tenancier de la taverne de l'Eau-profonde",
	found = "La taverne de l'Eau-profonde, Port de Menethil",
	hint = "Prenez une chambre à la taverne de l'Eau-profonde.",
	allegiance = "Royaume d'Ironforge",
	aliases = { "Helbrek" },
	sections = {
		{
			title = "Résumé",
			text = [=[Helbrek tient la taverne de l'Eau-profonde, la maison la plus animée du {link:menethil-harbor}Port de Menethil{/link}. Tous ceux qui débarquent dans les {link:wetlands}Paluns{/link} passent tôt ou tard sous son toit : marins descendus des navires, soldats venus de la route d'Algaz, érudits de la {link:explorers-league}Ligue des explorateurs{/link} attendant une escorte pour leurs fouilles. {link:mikhail}Mikhail{/link} sert les boissons à son comptoir. Un survivant ivre de la {link:third-fleet}Troisième flotte{/link} s'assied à ses tables, et tous les clients ne sont pas ce qu'ils semblent être.]=],
		},
		{
			title = "Non consigné",
			text = [=[On a peu écrit sur Helbrek lui-même. Sa taverne en dit plus sur le port que lui.]=],
