	},
	bonds = {
		{ id = "mikhail", name = "Mikhail", note = "son barman" },
		{ id = "first-mate-fitzsimmons", name = "Second Fitzsimmons", note = "un habitué" },
	},
})

Translate("frFR", "mikhail", {
	title = "Mikhail",
	subtitle = "Barman de la taverne de l'Eau-profonde",
	found = "Le comptoir de la taverne de l'Eau-profonde",
