			text = [=[Un client près de la porte écoutait un peu trop attentivement. C'était {link:tapoke-slim-jahn}Tapoke Jahn{/link}, dit Slim, et une fois pris, il parla. Il avait accepté l'argent des {link:defias-brotherhood}Défias{/link} pour faire monter leur homme à bord d'un navire royal dans le port. Mikhail jura que même un voleur doit garder un peu d'honneur, et fit aussitôt prévenir Elling.]=],
		},
	},
	mentions = {
		{ text = "Le diplomate disparu" },
		{ text = "Le diplomate disparu" },
		{ text = "Le diplomate disparu" },
		{
			text = [=[Le diplomate disparu, vers {link:theramore-isle}Theramore{/link}]=],
		},
	},
	bonds = {
		{ id = "elling-trias", name = "Elling Trias", note = "son vieil ami de Stormwind" },
		{ id = "tapoke-slim-jahn", name = "Tapoke « Slim » Jahn", note = "le traître qu'il démasqua" },
		{ id = "innkeeper-helbrek", name = "Aubergiste Helbrek", note = "son employeur" },
	},
})

Translate("frFR", "tapoke-slim-jahn", {
	title = "Tapoke « Slim » Jahn",
	subtitle = "Un traître dans la taverne",
	found = "La taverne de l'Eau-profonde, Port de Menethil",
	hint = [=[Surveillez le client qui écoute de trop près à la taverne de l'Eau-profonde.]=],
	allegiance = "Confrérie défias (contre paiement)",
	aliases = { "Slim", "Tapoke Jahn" },
	sections = {
		{
			title = "Résumé",
			text = [=[Tapoke Jahn, que la pègre appelle Slim, boit à la taverne de l'Eau-profonde et garde l'oreille tendue. Il fut payé par la {link:defias-brotherhood}Confrérie défias{/link} pour une seule tâche au {link:menethil-harbor}Port de Menethil{/link}, et il l'accomplit. Quand il apprit que des inconnus posaient des questions à son sujet, il tenta de s'éclipser par la porte.]=],
		},
	},
	chapters = {
		{
			title = "Ce que savait Slim",
			hint = "Arrêtez Slim avant qu'il ne s'échappe de la taverne.",
			text = [=[Slim n'était pas assez payé pour mourir pour les {link:defias-brotherhood}Défias{/link}, et il le dit. Le prisonnier qu'ils avaient pris n'était pas un diplomate. C'était le roi de {link:stormwind-city}Stormwind{/link}, qui faisait voile en secret vers {link:theramore-isle}Theramore{/link}. La part de Slim avait été de faire monter un homme, appelé {link:private-hendel}Hendel{/link}, à bord du navire du roi dans le port. Il croyait que les Défias travaillaient pour quelqu'un de plus grand qu'eux.]=],
		},
	},
	mentions = {
		{ text = "Le diplomate disparu" },
		{ text = "Le diplomate disparu" },
	},
	bonds = {
		{ id = "mikhail", name = "Mikhail", note = "le démasqua" },
		{ id = "varian-wrynn", name = "Varian Wrynn", note = "le roi qu'il aida à trahir" },
	},
})

Translate("frFR", "sida", {
	title = "Sida",
	subtitle = "Une femme de Menethil",
	found = "Port de Menethil, près des marchandises générales",
	hint = [=[Parlez à la femme de Menethil qui a perdu son sac au profit d'un limon.]=],
	allegiance = "Port de Menethil",
	sections = {
		{
			title = "Résumé",
			text = [=[Sida vit au {link:menethil-harbor}Port de Menethil{/link}. Une fois par semaine, elle marche jusqu'à la tombe d'Ironbeard, près de {link:dun-modr}Dun Modr{/link}, à travers une terre en guerre. Lors de sa dernière visite, les limons de la tombe vinrent pour elle. Prise de panique, elle jeta son sac sur l'un d'eux, et le limon l'avala tout entier. Elle s'en tira, mais le sac contenait une chose dont elle avait grand besoin.]=],
		},
		{
			title = "Non consigné",
			text = [=[Sida ne dit pas pourquoi elle visite la tombe, ni ce qu'elle gardait dans son sac. Le tanneur {link:james-halloran}James Halloran{/link} pensa un jour envoyer sa femme lui parler, sans dire pourquoi.]=],
		},
	},
	mentions = {
		{ text = "Fouiller dans le limon" },
		{ text = "Livraison quotidienne" },
	},
	bonds = {
		{ id = "james-halloran", name = "James Halloran", note = "un voisin qui parle d'elle" },
	},
})

