	sections = {
		{
			title = "Résumé",
			text = [=[Sylessa Duskwhisper est une {link:night-elves}elfe de la nuit{/link} venue au {link:menethil-harbor}Port de Menethil{/link} depuis {link:auberdine}Auberdine{/link} et le grand arbre {link:teldrassil}Teldrassil{/link}. Elle cherche une seule fleur. Parmi la cargaison du {i}Flying Osprey{/i}, perdu avec la {link:third-fleet}Troisième flotte{/link} au large de cette côte, se trouvait Nord'el, la Fleur des cieux. Elle fleurissait sous la pleine lune au sommet du mont Hyjal, l'ancien foyer de son peuple, et sa perte l'afflige encore.]=],
