	},
	mentions = {
		{ text = "La Fleur des cieux" },
	},
	bonds = {
		{ id = "glorin-steelbrow", name = "Glorin Steelbrow", note = "connaît la même épave" },
	},
})

Translate("frFR", "caitlin-grassman", {
	title = "Caitlin Grassman",
	subtitle = "Alchimiste de Menethil",
	found = "Port de Menethil",
	hint = [=[Parlez à l'alchimiste de Menethil qui a besoin du venin d'une araignée.]=],
	allegiance = "Port de Menethil",
	sections = {
		{
			title = "Résumé",
			text = [=[Caitlin Grassman pratique l'alchimie au {link:menethil-harbor}Port de Menethil{/link}, et les {link:wetlands}Paluns{/link} la tiennent occupée. Elle jure que tout est venimeux dans le marais, comme si le poison coulait dans la terre elle-même. Elle ne peut plus quitter le port tant qu'elle n'a pas préparé davantage d'antivenin. Pour cela, il lui faut une glande à venin des araignées du rocher de Thelgen, entière et intacte, ce qui est plus difficile à trouver qu'il n'y paraît.]=],
		},
	},
	mentions = {
		{ text = "Risques alchimiques" },
	},
})

Translate("frFR", "bart-tidewater", {
	title = "Bart Tidewater",
	subtitle = "Capitaine du Maiden's Virtue",
	found = "Les quais du Port de Menethil",
	hint = [=[Trouvez le capitaine autoproclamé qui arpente les quais de Menethil.]=],
	allegiance = "Port de Menethil",
	sections = {
		{
			title = "Résumé",
			text = [=[Bart Tidewater se dit capitaine du {i}Maiden's Virtue{/i} et arpente les quais de Menethil comme s'ils lui appartenaient. Tout le monde ne lui reconnaît pas ce titre. Une vieille connaissance appelée {link:tom-half-fish-wilson}Demi-poisson{/link} affirme que le {i}Virtue{/i} n'est jamais allé plus loin qu'un rocher de {link:tanaris}Tanaris{/link}, que Bart est un acteur qui gagna le navire aux cartes, et qu'il tricha pour y parvenir. Demi-poisson lui envoya malgré tout un cadeau.]=],
		},
	},
	mentions = {
		{ text = "Un manque de vertu" },
	},
})

Translate("frFR", "archaeologist-flagongut", {
	title = "Archéologue Flagongut",
	subtitle = "Érudit de la Ligue des explorateurs",
	found = "La taverne de l'Eau-profonde, Port de Menethil",
	hint = [=[Trouvez l'archéologue qui attend à la taverne de l'Eau-profonde une escorte pour les fouilles.]=],
	allegiance = "Ligue des explorateurs",
	aliases = { "Flagongut" },
	sections = {
		{
			title = "Résumé",
			text = [=[Flagongut est un archéologue de la {link:explorers-league}Ligue des explorateurs{/link}. Lors de l'une des conférences de la Ligue à {link:ironforge}Ironforge{/link}, il présenta un fossile qui, croyait-il, renfermait un pouvoir caché. Il trouva une relique, la pierre de Relu, qui selon lui pouvait le libérer. Sur la route des fouilles de {link:prospector-whelgar}Whelgar{/link}, des raptors l'attaquèrent et l'un d'eux avala la pierre. Depuis, il attend une escorte à la taverne de l'Eau-profonde.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il étudie les fossiles des fouilles de {link:prospector-whelgar}Whelgar{/link} et de celles de {link:prospector-remtravel}Remtravel{/link} à {link:darkshore}Sombrivage{/link}.
• Il cherche la pierre de Relu, perdue dans le ventre d'un raptor tacheté.]=],
		},
	},
	chapters = {
		{
			title = "La pierre de Relu",
			hint = "Apportez à l'archéologue les deux fossiles et la pierre.",
			text = [=[Avec la pierre et les deux fossiles devant lui, Flagongut se mit au travail. Ce qui lui répondit n'était pas un simple secret du passé. Un esprit fut invoqué, et il s'écria d'émerveillement.]=],
		},
	},
	mentions = {
		{ text = "Le prospecteur distrait" },
		{ text = "Le prospecteur distrait" },
	},
	bonds = {
		{ id = "prospector-whelgar", name = "Prospecteur Whelgar", note = "détient le fossile d'origine" },
		{ id = "prospector-remtravel", name = "Prospecteur Remtravel", note = "trouva l'autre fossile" },
		{ id = "archaeologist-hollee", name = "Archéologue Hollee", note = "lui envoya le fossile de Remtravel" },
	},
})

Translate("frFR", "tarrel-rockweaver", {
	title = "Tarrel Rockweaver",
	subtitle = "Époux de l'excavation",
	found = "La route au nord du Port de Menethil",
	hint = [=[Trouvez le nain inquiet qui attend des lettres devant Menethil.]=],
	allegiance = "Ligue des explorateurs",
	aliases = { "Tarrel" },
	sections = {
		{
			title = "Résumé",
			text = [=[Tarrel Rockweaver attend devant le {link:menethil-harbor}Port de Menethil{/link} des nouvelles de sa femme, {link:merrin-rockweaver}Merrin{/link}, qui travaille aux fouilles de {link:prospector-whelgar}Whelgar{/link}. Chaque semaine, elle lui écrivait. Puis deux semaines passèrent sans un mot. C'est un fervent érudit des fouilles, et une vieille amie de ses années d'études se souvient de lui avec tendresse. À Menethil, pourtant, il n'est qu'un mari effrayé.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il demande aux éclaireurs de {link:longbraid-the-grim}Longbraid{/link} de rechercher l'équipe de fouilles.
• Il pleure les morts des fouilles et aspire à un jour où le peuple de {link:magni-bronzebeard}Magni{/link} pourra vivre sans peur.]=],
		},
	},
	mentions = {
		{ text = "À la recherche de l'équipe de fouilles" },
		{ text = "À la recherche de l'équipe de fouilles" },
		{ text = "Amour non partagé" },
	},
	bonds = {
		{ id = "merrin-rockweaver", name = "Merrin Rockweaver", note = "sa femme" },
		{ id = "archaeologist-hollee", name = "Archéologue Hollee", note = "son ancienne camarade d'études" },
	},
})

Translate("frFR", "merrin-rockweaver", {
	title = "Merrin Rockweaver",
	subtitle = "Survivante des fouilles",
	found = "Le promontoire au-dessus des Excavations de Whelgar",
	hint = [=[Trouvez la fouilleuse qui a survécu aux raptors aux Excavations de Whelgar.]=],
	allegiance = "Ligue des explorateurs",
	aliases = { "Merrin" },
	sections = {
		{
			title = "Résumé",
			text = [=[Merrin Rockweaver était l'une des fouilleuses de l'équipe de {link:prospector-whelgar}Whelgar{/link}. Ils mettaient au jour des artefacts rares quand ils trouvèrent les premiers grands os, puis les raptors vinrent. Elle survécut parce qu'{link:ormer-ironbraid}Ormer Ironbraid{/link} tint bon pendant qu'elle et le prospecteur s'enfuyaient. Tous trois sont désormais pris au piège sur un promontoire au-dessus des ruines de leur travail.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle envoie une lettre à son mari {link:tarrel-rockweaver}Tarrel{/link} pour lui dire ce qui arriva aux fouilles.]=],
		},
	},
	mentions = {
		{ text = "À la recherche de l'équipe de fouilles" },
	},
	bonds = {
		{ id = "tarrel-rockweaver", name = "Tarrel Rockweaver", note = "son mari" },
		{ id = "ormer-ironbraid", name = "Ormer Ironbraid", note = "lui sauva la vie" },
		{ id = "prospector-whelgar", name = "Prospecteur Whelgar", note = "son chef" },
	},
})

Translate("frFR", "ormer-ironbraid", {
	title = "Ormer Ironbraid",
	subtitle = "Défenseur des fouilles",
	found = "Le promontoire au-dessus des Excavations de Whelgar",
	hint = [=[Trouvez le nain qui garde les survivants des fouilles de Whelgar.]=],
	allegiance = "Ligue des explorateurs",
	aliases = { "Ormer" },
	sections = {
		{
			title = "Résumé",
			text = [=[Ormer Ironbraid est le {link:dwarves}nain{/link} qui sauva ce qui pouvait l'être aux fouilles de {link:prospector-whelgar}Whelgar{/link}. Quand les raptors envahirent le site, il les tint en respect pendant que {link:merrin-rockweaver}Merrin{/link} et le vieux prospecteur fuyaient vers le promontoire. Il ne put sauver les autres. Il refuse de quitter les deux qu'il garde, alors il demande à d'autres d'accomplir la vengeance qu'il a préparée.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il demande que les raptors des fouilles soient repoussés, espèce par espèce.
• Il croit qu'un grand raptor appelé Sarltooth mena les autres jusqu'au site, et il veut sa mort.]=],
		},
	},
	mentions = {
		{ text = "La vengeance d'Ormer" },
		{ text = "La vengeance d'Ormer" },
		{ text = "La vengeance d'Ormer" },
	},
	bonds = {
		{ id = "merrin-rockweaver", name = "Merrin Rockweaver", note = "il la sauva" },
		{ id = "prospector-whelgar", name = "Prospecteur Whelgar", note = "il le sauva" },
	},
})

Translate("frFR", "prospector-whelgar", {
	title = "Prospecteur Whelgar",
	subtitle = "Chef des fouilles des Paluns",
	found = "Le promontoire au-dessus des Excavations de Whelgar",
	hint = [=[Cherchez le vieux prospecteur qui mène les fouilles de la Ligue des explorateurs dans les Paluns.]=],
	allegiance = "Ligue des explorateurs",
	aliases = { "Whelgar" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le prospecteur Whelgar mène les fouilles de la {link:explorers-league}Ligue des explorateurs{/link} qui portent son nom. Il est vieux, trop vieux, dit-il, pour descendre parmi les bêtes qui ont pris son camp. Mais son esprit est vif. Juste avant l'arrivée des raptors, il mit au jour une grande tablette, la {link:goaz-stone}pierre de Goaz{/link}, gravée dans l'écriture des titans et brisée en quatre endroits. Il croit que les morceaux manquants détiennent la clé d'un mystère plus grand que tous ceux que la Ligue a découverts.]=],
		},
		{
			title = "Importance",
			text = [=[La tablette de Whelgar parle d'un dessein divin et d'une prophétie funeste, et de Dieux très anciens enchaînés sous la terre. Peu de découvertes de la Ligue ont touché à des choses plus anciennes ou plus sombres.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il détient le fossile d'origine que l'archéologue {link:archaeologist-flagongut}Flagongut{/link} souhaite étudier.
• Il survécut à l'attaque des raptors sur ses fouilles avec {link:merrin-rockweaver}Merrin Rockweaver{/link} et {link:ormer-ironbraid}Ormer Ironbraid{/link}.
• Il s'efforce de traduire l'écriture titanesque de la pierre de Goaz.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique ne dit quelle fut la vie de Whelgar avant les fouilles, ni depuis combien de temps il sert la Ligue.]=],
		},
	},
	chapters = {
		{
			title = "La pierre de Goaz",
			hint = [=[Retrouvez les fragments manquants de la tablette du prospecteur.]=],
			text = [=[Les fragments se nommaient Ados, Modr, Golm et Neru, et ils gisaient dispersés dans les ruines des fouilles, parmi de vieilles reliques et de la terre meuble. Quand le dernier fut remis en place, Whelgar se pencha sur la pierre et commença à lire. De nouveaux mots lui vinrent aussitôt, et il les prononça à voix haute : des Dieux très anciens, enchaînés sous la terre. Il ne dit pas ce qu'il craignait qu'ils signifient. Il dit seulement que c'était le commencement de quelque chose de grand.]=],
		},
	},
	mentions = {
		{ text = "Découvrir le passé" },
		{ text = "Le prospecteur distrait" },
		{ text = "À la recherche de l'équipe de fouilles" },
	},
	bonds = {
		{ id = "merrin-rockweaver", name = "Merrin Rockweaver", note = "une fouilleuse de son équipe" },
		{ id = "ormer-ironbraid", name = "Ormer Ironbraid", note = "lui sauva la vie" },
		{ id = "archaeologist-flagongut", name = "Archéologue Flagongut", note = "veut son fossile" },
	},
})

Translate("frFR", "longbraid-the-grim", {
	title = "Longbraid le Sinistre",
	subtitle = "Commandant du régiment de Dun Modr",
	found = "Le camp devant Dun Modr",
	hint = [=[Cherchez le commandant nain qui tient le camp devant Dun Modr tombée.]=],
	allegiance = "Royaume d'Ironforge",
	aliases = { "Longbraid" },
	sections = {
		{
			title = "Résumé",
			text = [=[Longbraid le Sinistre menait le régiment d'{link:ironforge}Ironforge{/link} qui gardait {link:dun-modr}Dun Modr{/link} et le viaduc de Thandol. Il perdit les deux. Les {link:dark-iron-dwarves}Sombrefer{/link} firent sauter le pont ouest lors d'une embuscade, et son frère périt avec lui. Avant que le régiment ne puisse se reprendre, ils tombèrent sur la ville. Longbraid sonna le cor de la retraite, et il tient désormais un petit camp devant les murs avec les rares qui survécurent.]=],
		},
		{
			title = "Importance",
			text = [=[Longbraid est le chagrin et l'obstination de Khaz Modan en un seul {link:dwarves}nain{/link}. Il n'a ni réserve, ni alliés disponibles, ni ville, et pourtant il n'a pas quitté la route du nord.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il sonna la retraite quand {link:dun-modr}Dun Modr{/link} tomba, et sauva ce qui restait de son régiment.
• Il envoya un cavalier au sud, à Menethil, avec le blessé {link:harlo-barnaby}Harlo Barnaby{/link}.
• Il traque le démoniste qui mène les {link:dark-iron-dwarves}Sombrefer{/link} dans les {link:wetlands}Paluns{/link}.
• Il envoya un éclaireur, Ol' Rustlocke, au pont est, et l'éclaireur ne revint jamais.]=],
		},
	},
	chapters = {
		{
			title = "La chute de Dun Modr",
			hint = "Apportez des nouvelles du soldat blessé à Menethil.",
			text = [=[Longbraid apprit que le jeune {link:harlo-barnaby}Harlo{/link} avait survécu, et pendant un instant la nouvelle lui rendit espoir. Puis il raconta le reste sans détour. {link:dun-modr}Dun Modr{/link} était perdue. Le régiment qui l'avait tenue n'était plus que l'ombre de lui-même.]=],
		},
		{
			title = "Une sinistre besogne",
			hint = "Traquez le démoniste qui mène les Sombrefer.",
			text = [=[Les {link:dark-iron-dwarves}Sombrefer{/link} des {link:wetlands}Paluns{/link} étaient menés par {link:balgaras-the-foul}Balgaras le Répugnant{/link}, un démoniste qui envoyait les autres mourir et se tenait hors d'atteinte. Quand son oreille fut posée devant Longbraid, le commandant n'en tira aucune joie. Les morts ne reviendraient pas. Mais les vivants pourraient dormir, et il faudrait chasser le reste des Sombrefer avant qu'un nouveau maître n'arrive.]=],
		},
	},
	mentions = {
		{ text = "La chute de {link:dun-modr}Dun Modr{/link}" },
		{ text = "Une sinistre besogne" },
		{ text = "Une fureur profonde, son frère vengé" },
		{ text = "À la recherche de l'équipe de fouilles" },
	},
	bonds = {
		{ id = "motley-garmason", name = "Motley Garmason", note = "lié par l'honneur à rester à ses côtés" },
		{ id = "rhag-garmason", name = "Rhag Garmason", note = "son officier" },
		{ id = "harlo-barnaby", name = "Harlo Barnaby", note = "un soldat qu'il mit en sûreté" },
		{ id = "balgaras-the-foul", name = "Balgaras le Répugnant", note = "ennemi" },
		{ id = "kam-deepfury", name = "Kam Deepfury", note = "prépara la mort de son frère" },
	},
})

Translate("frFR", "motley-garmason", {
	title = "Motley Garmason",
	subtitle = "Soldat de Dun Modr",
	found = "Le camp devant Dun Modr",
	hint = [=[Parlez au nain du camp de Longbraid qui hait le plus les Sombrefer.]=],
	allegiance = "Royaume d'Ironforge",
	aliases = { "Motley" },
	sections = {
		{
			title = "Résumé",
			text = [=[Motley Garmason sert dans le régiment brisé de {link:longbraid-the-grim}Longbraid{/link}. Il est lié par l'honneur à rester aux côtés de son commandant, et cela l'exaspère. Pendant que les soldats d'{link:ironforge}Ironforge{/link} se battent pour l'{link:alliance}Alliance{/link} en des terres lointaines, dit-il, les propres foyers des nains tombent aux mains des {link:dark-iron-dwarves}Sombrefer{/link}. Il veut que le camp Sombrefer soit assez durement pressé pour que la réserve, si elle vient jamais, puisse achever le travail.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il appelle à frapper les {link:dark-iron-dwarves}Sombrefer{/link} de la colline de Morneforge.
• Il veut la tête de {link:kam-deepfury}Kam Deepfury{/link}, détenu à la {link:the-stockade}Prison de Stormwind{/link}, pour la mort du frère de {link:longbraid-the-grim}Longbraid{/link}.]=],
		},
	},
	mentions = {
		{ text = "La guerre des {link:dark-iron-dwarves}Sombrefer{/link}" },
		{ text = "Une fureur profonde" },
	},
	bonds = {
		{ id = "longbraid-the-grim", name = "Longbraid le Sinistre", note = "son commandant" },
		{ id = "rhag-garmason", name = "Rhag Garmason", note = "porte le même nom" },
		{ id = "kam-deepfury", name = "Kam Deepfury", note = "le conspirateur dont il veut la mort" },
	},
})

Translate("frFR", "rhag-garmason", {
	title = "Rhag Garmason",
	subtitle = "Soldat de Dun Modr",
	found = "Le camp devant Dun Modr",
	hint = [=[Parlez au nain du camp de Longbraid qui surveille le viaduc de Thandol.]=],
	allegiance = "Royaume d'Ironforge",
	aliases = { "Rhag" },
	sections = {
		{
			title = "Résumé",
			text = [=[Rhag Garmason entendit l'explosion qui déchira le viaduc de Thandol. Il surveille ce qui reste du pont depuis le camp de {link:longbraid-the-grim}Longbraid{/link}. Quand l'éclaireur Ebenezer Rustlocke ne revint pas, c'est Rhag qui découvrit pourquoi : le vieux {link:dwarves}nain{/link} était mort dans une embuscade, des ordres {link:dark-iron-dwarves}Sombrefer{/link} serrés à côté de lui. Ces ordres parlaient d'autres explosifs qui attendaient de l'autre côté de la gorge.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il chercha à connaître le sort d'Ol' Rustlocke.
• Il vit le dernier pont du viaduc sauvé d'une seconde explosion.
• Il envoya une demande de soldats au capitaine {link:captain-nials}Nials{/link}, au {link:refuge-pointe}Refuge de l'Ornière{/link} dans les {link:arathi-highlands}Hautes-terres d'Arathi{/link}. La réponse fut non. {link:stromgarde-keep}Stromgarde{/link} était tombée, et ses propres soldats avaient une ville à reconquérir.]=],
		},
	},
	mentions = {
		{ text = "{link:thandol-span}Le viaduc de Thandol{/link}" },
		{ text = "{link:thandol-span}Le viaduc de Thandol{/link}" },
		{ text = "{link:thandol-span}Le viaduc de Thandol{/link}" },
		{ text = "Appel à l'{link:alliance}Alliance{/link}" },
	},
	bonds = {
		{ id = "longbraid-the-grim", name = "Longbraid le Sinistre", note = "son commandant" },
		{ id = "motley-garmason", name = "Motley Garmason", note = "porte le même nom" },
	},
})

Translate("frFR", "roggo-harlbarrow", {
	title = "Roggo Harlbarrow",
	subtitle = "Éclaireur de Dun Modr",
	found = "Le camp devant Dun Modr",
	hint = [=[Trouvez le nain du camp de Longbraid qui rassemble les nouvelles de l'ennemi.]=],
	allegiance = "Royaume d'Ironforge",
	aliases = { "Roggo" },
	sections = {
		{
			title = "Résumé",
			text = [=[Roggo Harlbarrow est les yeux et les oreilles du camp de {link:longbraid-the-grim}Longbraid{/link}. C'est lui qui apprit qu'un démoniste appelé {link:balgaras-the-foul}Balgaras le Répugnant{/link} mène les {link:dark-iron-dwarves}Sombrefer{/link} dans les {link:wetlands}Paluns{/link}, et lui qui prouva que {link:kam-deepfury}Kam Deepfury{/link} avait préparé l'attaque du viaduc de Thandol. Il a aussi tenté, encore et encore, de joindre les forces de réserve d'{link:ironforge}Ironforge{/link}. Aucune n'a répondu.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il désigna {link:balgaras-the-foul}Balgaras le Répugnant{/link} comme le chef des {link:dark-iron-dwarves}Sombrefer{/link}.
• Il rassembla les preuves contre {link:kam-deepfury}Kam Deepfury{/link}.
• Il parla à {link:rhag-garmason}Rhag{/link} du camp de l'{link:alliance}Alliance{/link} au {link:refuge-pointe}Refuge de l'Ornière{/link}.]=],
		},
	},
	bonds = {
		{ id = "longbraid-the-grim", name = "Longbraid le Sinistre", note = "son commandant" },
	},
})

Translate("frFR", "ashlan-stonesmirk", {
	title = "Ashlan Stonesmirk",
	subtitle = "Expert en explosifs de Dun Modr",
	found = "Le camp devant Dun Modr",
	hint = "Trouvez l'expert en explosifs du camp de Longbraid.",
	allegiance = "Royaume d'Ironforge",
	aliases = { "Ashlan" },
	sections = {
		{
			title = "Résumé",
			text = [=[Ashlan Stonesmirk fut affecté au régiment de {link:dun-modr}Dun Modr{/link} pour sa connaissance de la poudre explosive. Quand une poudre étrange fut trouvée près du barrage de Formepierre, dans le {link:loch-modan}Loch Modan{/link}, on la lui envoya. Il la reconnut aussitôt à ses cristaux argentés et à son odeur : du seaforium. Sèche, elle est inoffensive. Mouillée, elle pourrait faire sauter {link:ironforge}Ironforge{/link} elle-même hors de la montagne. Il savait aussi comment la rendre inoffensive.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il identifia la poudre {link:dark-iron-dwarves}Sombrefer{/link} et donna la recette pour la désamorcer.]=],
		},
	},
	mentions = {
		{ text = "Une sombre menace se profile" },
		{ text = "Une sombre menace se profile" },
	},
	bonds = {
		{ id = "chief-engineer-hinderweir-vii", name = "Ingénieur en chef Hinderweir VII", note = "lui envoya la poudre" },
	},
})

Translate("frFR", "harlo-barnaby", {
	title = "Harlo Barnaby",
	subtitle = "Soldat blessé de Dun Modr",
	found = "Port de Menethil",
	hint = "Parlez au soldat blessé qui s'est réveillé à Menethil.",
	allegiance = "Royaume d'Ironforge",
	aliases = { "Harlo" },
	sections = {
		{
			title = "Résumé",
			text = [=[Harlo Barnaby est un jeune soldat du régiment de {link:longbraid-the-grim}Longbraid{/link}. Alors que les nains fuyaient {link:dun-modr}Dun Modr{/link}, une hache perdue le frappa dans le dos et tout devint noir. Il se réveilla au {link:menethil-harbor}Port de Menethil{/link}, loin des combats, sans savoir qui d'autre avait survécu. Ses blessures sont graves, mais son espoir n'est pas perdu. Il croit que Longbraid vit encore.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il demande des nouvelles de {link:longbraid-the-grim}Longbraid{/link} et de son régiment.]=],
		},
	},
	mentions = {
		{ text = "La chute de {link:dun-modr}Dun Modr{/link}" },
	},
	bonds = {
		{ id = "longbraid-the-grim", name = "Longbraid le Sinistre", note = "son commandant, qui le mit en sûreté" },
	},
})

Translate("frFR", "balgaras-the-foul", {
	title = "Balgaras le Répugnant",
	subtitle = "Démoniste des Sombrefer",
	found = [=[Parmi les Sombrefer de Dun Modr et de la colline de Morneforge]=],
	hint = [=[Traquez le démoniste Sombrefer qui se cache derrière ses soldats.]=],
	allegiance = "Nains Sombrefer",
	aliases = { "Balgaras" },
	sections = {
		{
			title = "Résumé",
			text = [=[Balgaras le Répugnant commande les {link:dark-iron-dwarves}Sombrefer{/link} dans les {link:wetlands}Paluns{/link}. C'est un démoniste et, de l'avis de tous, un lâche. Il envoie ses soldats faire son travail et se tient loin du danger, allant et venant entre les ruines de {link:dun-modr}Dun Modr{/link} et le camp de la colline de Morneforge. De nombreux nains d'{link:ironforge}Ironforge{/link} moururent sur ses ordres.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il mène les {link:dark-iron-dwarves}Sombrefer{/link} qui prirent {link:dun-modr}Dun Modr{/link}.
• Il échappe depuis longtemps aux chasseurs de {link:longbraid-the-grim}Longbraid{/link}.]=],
		},
	},
	mentions = {
		{ text = "Une sinistre besogne" },
	},
	bonds = {
		{ id = "longbraid-the-grim", name = "Longbraid le Sinistre", note = "veut son oreille" },
	},
})

Translate("frFR", "captain-halyndor", {
	title = "Capitaine Halyndor",
	subtitle = "Capitaine de l'Intrepid",
	found = "L'épave de l'Intrepid, la flotte perdue",
	hint = "Affrontez le capitaine noyé qui arpente encore l'Intrepid.",
	allegiance = "La Troisième flotte engloutie",
	aliases = { "Halyndor" },
	sections = {
		{
			title = "Résumé",
			text = [=[Halyndor était capitaine de l'{i}Intrepid{/i}, un navire de la {link:third-fleet}Troisième flotte{/link} de {link:kul-tiras}Kul Tiras{/link}. Il gardait la clé de son coffre-fort, et dans ce coffre se trouvait un Œil de Paleth maudit. Quand les dragons rouges coulèrent la flotte, Halyndor sombra avec son navire. Il ne l'a pas quitté. Son second, l'unique survivant, le maudit d'avoir mené la flotte à sa perte.]=],
		},
	},
	mentions = {
		{ text = "Lever la malédiction" },
	},
	bonds = {
		{ id = "first-mate-fitzsimmons", name = "Second Fitzsimmons", note = "le blâme" },
	},
})

Translate("frFR", "rethiel-the-greenwarden", {
	title = "Rethiel le Gardien vert",
	subtitle = "Esprit du marais",
	found = "Le marais à l'est de l'embranchement vers Dun Modr",
	hint = [=[Cherchez l'esprit du marais parmi les crocilisques à l'est de la route de Dun Modr.]=],
	allegiance = "Les Paluns",
	aliases = { "Le Gardien vert", "Rethiel" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Gardien vert est un esprit du marais vivant. Les marins de Menethil en parlent comme d'une bête qui coupe les hommes en deux d'un coup de dents. La vérité est plus étrange. Il a de nombreux noms et ne répond qu'à peu d'entre eux, mais ceux en qui il a confiance peuvent l'appeler Rethiel. Il ressent les {link:wetlands}Paluns{/link} comme son propre corps. Il dit que la terre pleure de plaies qui s'infectent, et que les peuples du monde ont déjà mis sa foi à l'épreuve.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il demande que les gnolls Poil-moussu soient décimés, car ils sont devenus trop nombreux pour la terre.
• Il brise les silex à feu des gnolls et les jette à la mer.
• Il cherche à rendre au marais les rampants des marais fiévreux.]=],
		},
	},
	mentions = {
		{ text = "Le Gardien vert" },
		{ text = "Pattes piétinantes" },
		{ text = "Le tabou du feu" },
		{ text = "Des cloques sur la terre" },
	},
	bonds = {
		{ id = "first-mate-fitzsimmons", name = "Second Fitzsimmons", note = "détourne de lui ceux qui le cherchent" },
	},
})

Translate("frFR", "howin-kindfeather", {
	title = "Howin Kindfeather",
	subtitle = "Chevaucheur de griffon des Paluns",
	found = [=[Un camp à l'écart de la route, à l'est des Excavations de Whelgar]=],
	hint = [=[Trouvez le nain et son griffon campés à l'écart de la route, à l'est des fouilles de Whelgar.]=],
	allegiance = "Clan Wildhammer",
	aliases = { "Howin" },
	sections = {
		{
			title = "Résumé",
			text = [=[Howin Kindfeather campe à l'écart de la route des {link:wetlands}Paluns{/link} avec son griffon, Bassbeak. Il envoya un jour l'oiseau à Menethil avec une lettre pour commander des écailles de dragonnet, ce dont le tanneur du port s'émerveille encore. Il crache quand il parle des {link:dark-iron-dwarves}Sombrefer{/link}, des Dragonmaw et des drakes qu'ils montaient, et il ne sait pas lesquels il hait le plus. Il entend remettre les choses en ordre. Son plan exige une cape contre le feu des dragons, des dents pour la coudre et un griffon au ventre plein.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il achète les écailles des dragonnets cramoisis, qui protègent du feu des dragons.
• Il rassemble des dents et des œufs de tranchegueule pour son plan.]=],
		},
	},
	mentions = {
		{ text = "Livraison de caisse cramoisie" },
		{ text = "Aiguilles de tranchegueule" },
		{ text = "Temps difficiles" },
	},
	bonds = {
		{ id = "james-halloran", name = "James Halloran", note = "lui vendit les écailles" },
	},
})

Translate("frFR", "hervdana-saegrund", {
	title = "Hervdana Saegrund",
	subtitle = "Chamane des chutes du sud",
	found = "Une grotte sous les chutes du sud",
	hint = [=[Cherchez la chamane dont la famille vit dans une grotte sous les chutes du sud.]=],
	allegiance = "Chamans",
	aliases = { "Hervdana" },
	sections = {
		{
			title = "Résumé",
			text = [=[Hervdana Saegrund est une chamane dont la famille vit dans une grotte sous les chutes du sud des {link:wetlands}Paluns{/link}, avec Frothrik Saegrund parmi eux. {link:norric-lochthane}Norric Lochthane{/link} lui envoie ses élèves. Elle enseigne que l'eau doit être comprise sous toutes ses formes : douce là où elle rencontre l'eau saumâtre, souillée là où quelque chose de sombre s'y est infiltré, et pure là où elle est restée intacte depuis des âges. Ses élèves recueillent de l'eau dans les {link:redridge-mountains}Carmines{/link} et en {link:ashenvale}Orneval{/link} avant de retourner auprès de Norric.]=],
		},
	},
	mentions = {
		{ text = "L'appel de l'eau" },
		{ text = "L'appel de l'eau, au pied des chutes" },
		{
			text = [=[L'appel de l'eau, depuis les chutes de {link:stonewatch-keep}Guet-de-pierre{/link}]=],
		},
		{ text = "L'appel de l'eau, depuis {link:astranaar}Astranaar{/link}" },
		{
			text = [=[L'appel de l'eau, retour auprès de {link:norric-lochthane}Norric{/link}]=],
		},
	},
	bonds = {
		{ id = "norric-lochthane", name = "Norric Lochthane", note = "lui envoie ses élèves" },
	},
})

Translate("frFR", "chieftain-nek-rosh", {
	title = "Chef Nek'rosh",
	subtitle = "Chef des Dragonmaw",
	found = "Campement de Hargnecroc",
	hint = [=[Affrontez le chef qui mène les Dragonmaw depuis leur camp dans les collines de l'est.]=],
	allegiance = "Clan Dragonmaw",
	aliases = { "Nek'rosh" },
	sections = {
		{
			title = "Résumé",
			text = [=[Nek'rosh est le chef du {link:dragonmaw-clan}clan Dragonmaw{/link} dans les {link:wetlands}Paluns{/link}. Il est le fils de Nekros, qui mena le clan dans les années où il retenait captifs les dragons rouges. Nekros plia les dragons à sa volonté grâce à une puissante magie. Quand la magie faillit, les dragons se retournèrent contre leurs maîtres, et Nekros fut tué. Son fils a juré de se venger des dragons qui l'ont tué.]=],
		},
		{
			title = "Importance",
			text = [=[Sous Nek'rosh, un clan brisé est redevenu une armée. Les Dragonmaw ont poussé jusque dans {link:dun-algaz}Dun Algaz{/link}, construit des engins de siège et tourné leurs regards vers le {link:menethil-harbor}Port de Menethil{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il rassembla les Dragonmaw dispersés au campement de Hargnecroc.
• Il lança ses guerriers dans {link:dun-algaz}Dun Algaz{/link}, coupant la route entre Menethil et {link:the-loch}le Loch{/link} Modan.
• Il construisit des catapultes pour assiéger le {link:menethil-harbor}Port de Menethil{/link}.]=],
		},
		{
			title = "Non consigné",
			text = [=[Les chroniques de la {link:second-war}Deuxième Guerre{/link} parlent des Dragonmaw qui retenaient la Reine des dragons à {link:grim-batol}Grim Batol{/link}. Quel rôle Nek'rosh lui-même joua en ces années, elles ne le disent pas.]=],
		},
	},
	chapters = {
		{
			title = "Le fils de Nekros",
			hint = [=[Portez les bannières de guerre des Dragonmaw au capitaine du donjon de Menethil.]=],
			text = [=[Quand on déposa les bannières devant lui, le capitaine {link:captain-stoutfist}Stoutfist{/link} raconta ce que les nains savaient de leur ennemi. Les Dragonmaw n'étaient plus ce qu'ils avaient été quand ils montaient des dragons. Leur chef était le fils de l'{link:orcs}orc{/link} qui avait jadis asservi le vol rouge, et il n'avait pas oublié comment son père était mort.]=],
		},
		{
			title = "Vaincre Nek'rosh",
			hint = "Brûlez les catapultes et abattez le chef.",
			text = [=[Les catapultes brûlèrent d'abord, et Menethil fut à l'abri d'elles. Puis Nek'rosh tomba dans son propre camp. {link:captain-stoutfist}Stoutfist{/link} jugea que c'était un coup décisif, dont le clan pourrait ne jamais se remettre.]=],
		},
	},
	mentions = {
		{ text = "Bannières de guerre" },
		{ text = "Le coup de Nek'rosh" },
		{ text = "Vaincre Nek'rosh" },
	},
	bonds = {
		{ id = "captain-stoutfist", name = "Capitaine Stoutfist", note = "ennemi" },
		{ id = "ma-ruk-wyrmscale", name = "Ma'ruk Wyrmscale", note = "son seigneur de guerre à Dun Algaz" },
		{ id = "alexstrasza", name = "Alexstrasza", note = "reine des dragons que son père asservit" },
	},
})

Translate("frFR", "ma-ruk-wyrmscale", {
	title = "Ma'ruk Wyrmscale",
	subtitle = "Seigneur de guerre dragonmaw",
	found = "Dun Algaz",
	hint = [=[Affrontez le seigneur de guerre dragonmaw qui tient le col de Dun Algaz.]=],
	allegiance = "Clan Dragonmaw",
	aliases = { "Ma'ruk" },
	sections = {
		{
			title = "Résumé",
			text = [=[Ma'ruk Wyrmscale est un seigneur de guerre du {link:dragonmaw-clan}clan Dragonmaw{/link}. Il mène les orcs descendus dans le col de {link:dun-algaz}Dun Algaz{/link}, où ils tendent des embuscades à tout voyageur entre {link:the-loch}le Loch{/link} Modan et les {link:wetlands}Paluns{/link}. Tant qu'il tient le col, aucun renfort n'atteint le {link:menethil-harbor}Port de Menethil{/link} par voie de terre.]=],
		},
		{
			title = "Importance",
			text = [=[Ma'ruk est le fil de la lame de {link:chieftain-nek-rosh}Nek'rosh{/link}. Le siège de Menethil voulu par le chef dépend de sa mainmise sur le col.]=],
		},
	},
	bonds = {
		{ id = "chieftain-nek-rosh", name = "Chef Nek'rosh", note = "son chef" },
	},
})

Translate("frFR", "dragonmaw-clan", {
	title = "Clan Dragonmaw",
	aliases = { "clan Dragonmaw", "orcs Dragonmaw" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Dragonmaw sont un clan d'{link:orcs}orcs{/link} de l'ancienne {link:horde}Horde{/link}. Pendant la {link:second-war}Deuxième Guerre{/link}, ils firent ce qu'aucun autre clan ne put faire : ils firent des dragons rouges leurs serviteurs. Depuis leur place forte de {link:grim-batol}Grim Batol{/link}, ils retinrent captive {link:alexstrasza}Alexstrasza{/link}, la Reine des dragons, par le pouvoir d'un artefact qu'avait forgé {link:deathwing}Aile-de-mort{/link}, et ils élevèrent ses petits comme montures de guerre. Des dragons rouges montés par des orcs Dragonmaw incendièrent les navires de l'{link:alliance}Alliance{/link} en mer.]=],
		},
		{
			title = "La chute",
			text = [=[La magie qui liait les dragons faillit. Le vol rouge se retourna contre le clan et le traqua sans pitié. Nekros, qui avait mené les Dragonmaw, fut tué, et le clan fut presque anéanti. Les rares survivants fuirent {link:grim-batol}Grim Batol{/link} et se cachèrent dans les montagnes à l'est de la route des {link:wetlands}Paluns{/link}.]=],
		},
		{
			title = "En ces jours",
			text = [=[Les Dragonmaw ont repris des forces sous le chef {link:chieftain-nek-rosh}Nek'rosh{/link}, fils de Nekros. Depuis le campement de Hargnecroc et le repaire caché de {link:dragonmaw-retreat}Dragonmaw Retreat{/link}, ils frappent vers l'ouest, et ils se sont emparés du col de {link:dun-algaz}Dun Algaz{/link}. Ils construisent des catapultes, amassent des armes et, murmure-t-on, rêvent encore de dragons. Les nains de Menethil les disent féroces, mais ils savent que le clan sans ses dragons est une menace moindre que le clan qui obscurcissait jadis le ciel.]=],
		},
	},
})

Translate("frFR", "third-fleet", {
	title = "Troisième flotte",
	aliases = { "La Troisième flotte", "la flotte maudite" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Troisième flotte de {link:kul-tiras}Kul Tiras{/link} prit la mer pendant la {link:second-war}Deuxième Guerre{/link}, la dernière grande guerre contre la {link:horde}Horde{/link}. Ses navires venaient des côtes de {link:lordaeron}Lordaeron{/link}, et au moins un vaisseau qui ne lui appartenait pas la rejoignit pour sa protection : le {i}Flying Osprey{/i}, qui transportait une cargaison de fer de forgelumière. Au large de la côte des {link:wetlands}Paluns{/link}, des orcs montés sur des dragons rouges s'abattirent sur la flotte. Les navires brûlèrent et sombrèrent, et les épaves gisent encore le long du rivage nord-ouest, en un lieu appelé la flotte perdue.]=],
		},
		{
			title = "La malédiction",
			text = [=[Quelque chose fut caché à bord de l'{i}Intrepid{/i} : un Œil de Paleth maudit, enfermé dans le coffre-fort du capitaine. Les Yeux furent faits par des prêtres humains pour briller d'une lumière sacrée, mais celui-ci avait été témoin de trop de chagrin. Son pouvoir retient les équipages noyés dans leurs coques pourrissantes. Un seul homme de la flotte vit encore, le second {link:first-mate-fitzsimmons}Fitzsimmons{/link}, et il boit à Menethil pour ne pas rêver d'eux.]=],
		},
		{
			title = "La cargaison",
			text = [=[Les murlocs de la côte ont fouillé le {i}Flying Osprey{/i}. Ses lingots de fer de forgelumière sont prisés de ceux qui combattent les morts-vivants. Une {link:night-elves}elfe de la nuit{/link} de {link:teldrassil}Teldrassil{/link}, {link:sylessa-duskwhisper}Sylessa Duskwhisper{/link}, dit que le navire transportait aussi Nord'el, une fleur du mont Hyjal.]=],
		},
	},
})

Translate("frFR", "goaz-stone", {
	title = "Pierre de Goaz",
	aliases = { "La pierre de Goaz" },
	sections = {
		{
			title = "Résumé",
			text = [=[La pierre de Goaz est une grande tablette mise au jour par le prospecteur {link:prospector-whelgar}Whelgar{/link} lors de ses fouilles dans les {link:wetlands}Paluns{/link}, juste avant que les raptors ne les envahissent. Elle est gravée dans l'écriture des titans. Quand on la trouva, elle était brisée en quatre endroits, et les morceaux perdus portaient les noms d'Ados, Modr, Golm et Neru. Même incomplète, la tablette parlait d'un dessein divin et d'une prophétie funeste.]=],
		},
		{
			title = "La lecture",
			text = [=[Quand les quatre fragments furent restaurés, {link:prospector-whelgar}Whelgar{/link} entreprit le lent travail de traduction. Les premiers mots nouveaux qu'il lut parlaient de Dieux très anciens, enchaînés sous la terre. La {link:explorers-league}Ligue des explorateurs{/link} a déjà trouvé des gravures des titans, mais rarement qui parlent aussi clairement de ce qui gît en dessous.]=],
		},
		{
			title = "Le temps présent",
			text = [=[{link:prospector-whelgar}Whelgar{/link} n'a pas achevé sa lecture. Au-dessus de ses fouilles, dans les collines, une brume a commencé à descendre des montagnes et des créations des titans marchent de nouveau. Si la pierre et l'éveil des hautes terres sont liés, la Ligue ne le sait pas encore.]=],
		},
	},
})
